import java.util.Scanner;

public class RollSearch {
    // Binary search in a sorted list of ten roll numbers
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] roll = new int[10];
        for (int i = 0; i < roll.length; i++)
            roll[i] = sc.nextInt();
        int key = sc.nextInt();
        int low = 0, high = roll.length - 1, pos = -1, steps = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            steps++;
            if (roll[mid] == key) {
                pos = mid;
                break;
            } else if (key > roll[mid])
                low = mid + 1;
            else
                high = mid - 1;
        }
        if (pos == -1)
            System.out.println("Roll number " + key + " is not in the list");
        else
            System.out.println("Roll number " + key + " is at position " + (pos + 1));
        System.out.println("Comparisons made = " + steps);
    }
}
