        boolean swapped = true;
        for (int i = 0; i < n - 1 && swapped; i++) {
            swapped = false;
            passes++;
            for (int j = 0; j < n - 1 - i; j++) {
                if (price[j] > price[j + 1]) {
                    int t = price[j];
                    price[j] = price[j + 1];
                    price[j + 1] = t;
                    swapped = true;
                    swaps++;
                }
            }
            String line = "Pass " + passes + ":";
            for (int k = 0; k < n; k++)
                line = line + " " + price[k];
            System.out.println(line);
        }
        System.out.println("Passes = " + passes + ", swaps = " + swaps);
    }
}
