import java.util.Scanner;

public class AgeSearch {
    // Sorts seven ages by selection sort and finds one by binary search
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] age = new int[7];
        for (int i = 0; i < age.length; i++)
            age[i] = sc.nextInt();
        int n = age.length;
        for (int i = 0; i < n - 1; i++) {
            int min = i;
            for (int j = i + 1; j < n; j++)
                if (age[j] < age[min])
                    min = j;
            int t = age[i];
            age[i] = age[min];
            age[min] = t;
        }
        String line = "Sorted:";
        for (int k = 0; k < n; k++)
            line = line + " " + age[k];
        System.out.println(line);
        int key = sc.nextInt();
        int low = 0, high = n - 1, pos = -1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (age[mid] == key) {
                pos = mid;
                break;
            } else if (key > age[mid])
                low = mid + 1;
            else
                high = mid - 1;
        }
        System.out.println(pos == -1 ? "Not found" : "Found at index " + pos);
    }
}
```

